section.script:
// DT8_HB_CATALOG_QUERY_V2: Product IDs and prices from company8 website1 database only.
// DT8_HB_CART_USER_SCOPED_V2: Dalla Terra pricebook and shower planner use the same per-user enquiry key.
window.hbIsGuest = ;
window.hbCartStorageKey = "";
window.hydroblokCatalog={
    'HBWB366012':{name:'36" x 60" x 1/2" Wallboard',price:0,id:null},'HBWB486412':{name:'48" x 64" x 1/2" Wallboard',price:0,id:null},
    'HBWB489612':{name:'48" x 96" x 1/2" Wallboard',price:0,id:null},'HBWB366058':{name:'36" x 60" x 5/8" Wallboard',price:0,id:null},
    'HBJSCART':{name:'Joint Sealant Cartridges 10 oz.',price:0,id:null},'HBJSSAUS':{name:'Joint Sealant Sausages 20 oz.',price:0,id:null},
    'HBSCREWWASH100':{name:'Screws and Washers (100 box)',price:0,id:null},'HBLPSP3636':{name:'36" x 36" LOW-PROFILE Shower Pan w/Drain',price:0,id:null},
    'HBLPSP3648':{name:'36" x 48" LOW-PROFILE Shower Pan w/Drain',price:0,id:null},'HBLPSP3660':{name:'36" x 60" LOW-PROFILE Shower Pan w/Drain',price:0,id:null},
    'HBLPSP3672':{name:'36" x 72" LOW-PROFILE Shower Pan w/Drain',price:0,id:null},'HBLPSP3672OD':{name:'36" x 72" Offset Drain LOW-PROFILE Shower Pan',price:0,id:null},
    'HBLPSP4848':{name:'48" x 48" LOW-PROFILE Shower Pan w/Drain',price:0,id:null},'HBLPSP4860':{name:'48" x 60" LOW-PROFILE Shower Pan w/Drain',price:0,id:null},
    'HBLPSP4872':{name:'48" x 72" LOW-PROFILE Shower Pan w/Drain',price:0,id:null},'HBLPSP6060':{name:'60" x 60" LOW-PROFILE Shower Pan w/Drain',price:0,id:null},
    'HBSSSP3660':{name:'Single Slope 36" x 60" Shower Pan',price:0,id:null},'HBSSSP6036':{name:'Single Slope 60" x 36" Shower Pan',price:0,id:null},
    'HBSSSP4872':{name:'Single Slope 48" x 72" Shower Pan',price:0,id:null},'HBSSSP7248':{name:'Single Slope 72" x 48" Shower Pan',price:0,id:null},
    'HBTSSSP3660':{name:'THIN Single Slope 36" x 60" Shower Pan',price:0,id:null},'HBTSSSP6036':{name:'THIN Single Slope 60" x 36" Shower Pan',price:0,id:null},
    'HBTSSSP4872':{name:'THIN Single Slope 48" x 72" Shower Pan',price:0,id:null},'HBTSSSP7248':{name:'THIN Single Slope 72" x 48" Shower Pan',price:0,id:null},
    'HBFLJCK':{name:'24 sq ft Floor Lowering Joist Clip Kit',price:0,id:null},'HBLDSLOTEXT':{name:'Slot Extender Stick',price:0,id:null},
    'HBLPSP1272EXT':{name:'Presloped 12" x 72" LOW-PROFILE Pan Extension',price:0,id:null},'HBSSSP1872EXT':{name:'Single Slope 18" x 72" Side Extension',price:0,id:null},
    'HBTSSSP7212EXT':{name:'THIN Single Slope 72" x 12" Pan Extension',price:0,id:null},'HBINSHADOW':{name:'Wall Drain (Concealed)',price:0,id:null},
    'HBINSI14':{name:'Floor Drain (1/4" Metal Edge)',price:0,id:null},'HBINSI38':{name:'Floor Drain (3/8" Metal Edge)',price:0,id:null},
    'HBINSI12':{name:'Floor Drain (1/2" Metal Edge)',price:0,id:null},'HBLD73':{name:'73.5" Line Drain Body Kit',price:0,id:null},
    'HBLDCOUP':{name:'Line Drain Coupler',price:0,id:null},'HBSC312460':{name:'Standard Curb 60" x 3½" x 4"',price:0,id:null},
    'HBSC312484':{name:'Standard Curb 84" x 3½" x 4"',price:0,id:null},'HBSCM60':{name:'MINI Curb 60" x 2" x 2 1/2"',price:0,id:null},
    'HBSCM84':{name:'MINI Curb 84" x 2" x 2 1/2"',price:0,id:null},'HBRSN1616':{name:'16" x 16" Recessed Niche',price:0,id:null},
    'HBRSN1628':{name:'16" x 28" Recessed Niche',price:0,id:null},'HBRBHSN1622':{name:'16" x 22" Recessed Barrel Head Niche',price:0,id:null},
    'HBRDWSN3216':{name:'32" x 16" Recessed Double Wide Niche',price:0,id:null},'HBRDASN3226':{name:'32" x 26" Recessed Double Arch Niche',price:0,id:null},
    'HBSBM':{name:'Suspended Bench Medium 17" x 17"',price:0,id:null},'HBSBL':{name:'Suspended Bench Large 22" x 22"',price:0,id:null},
    'HBDBM':{name:'Diamond Bench Medium 17" x 17"',price:0,id:null},'HBDBL':{name:'Diamond Bench Large 22" x 22"',price:0,id:null},
    'HBDSC':{name:'Diamond Shampoo Caddy 8" x 8"',price:0,id:null}
};










    var hbSku = '';
    if (!window.hydroblokCatalog[hbSku]) {
        var hbDims = hbSku.match(/^HBLPSP(\d{2})(\d{2})$/);
        window.hydroblokCatalog[hbSku] = { name: hbDims ? (hbDims[1] + '" x ' + hbDims[2] + '" Low-profile shower pan') : hbSku, price: 0, id: null };
    }
    if (window.hydroblokCatalog[hbSku]) {
        window.hydroblokCatalog[''].price = ;
        window.hydroblokCatalog[''].id = ;
    }

// 
    document.addEventListener('DOMContentLoaded', function() {
        let currentBom = {};
        let wallData = [{id:1, name:'Left Wall', w:36, h:96}, {id:2, name:'Back Wall', w:72, h:96}, {id:3, name:'Right Wall', w:36, h:96}];
        let wallCounter = 3;
        let hbLastFootprint = {w:72,d:36};
        let hbEntryFollowsFootprint = true; // DT8_HB_PRODUCTION_ENTRY_WIDTH_RESTORE_20261015_V1
        const hbEntryInput = document.getElementById('entry_w');
        if (hbEntryInput) hbEntryInput.addEventListener('input', function(){ hbEntryFollowsFootprint = false; }); // DT8_HB_UX_VALIDATION_WALL_LINK_ENTRY_20261015_V1

        function getVal(id) { const el = document.getElementById(id); return el ? parseFloat(el.value) || 0 : 0; }
        function getStr(id) { const el = document.getElementById(id); return el ? el.value : 'none'; }

        function getAbsoluteUrl(url) {
            if (!url) return '';
            if (url.startsWith('http')) return url;
            if (url.startsWith('//')) return window.location.protocol + url;
            return window.location.origin + (url.startsWith('/') ? '' : '/') + url;
        }

        setInterval(function() {
            const webLogo = document.querySelector('.web-hb-logo');
            const printHbLogo = document.getElementById('print_hb_logo');
            if (webLogo && printHbLogo && webLogo.src && printHbLogo.src !== webLogo.src) printHbLogo.src = webLogo.src;
            const siteLogo = document.querySelector('header img.img-fluid, header .navbar-brand img, .o_header_logo img');
            const printDtLogo = document.getElementById('print_dt_logo');
            if (siteLogo && printDtLogo && siteLogo.src && printDtLogo.src !== siteLogo.src) printDtLogo.src = siteLogo.src;
        }, 1000);

        document.addEventListener('click', function(e) {
            if(e.target.classList.contains('click-zoom') || e.target.closest('.click-zoom')) {
                e.preventDefault();
                let imgSrc = '';
                if(e.target.tagName === 'IMG') imgSrc = e.target.src;
                else if(e.target.tagName === 'CANVAS') imgSrc = e.target.toDataURL();
                else if(e.target.querySelector('img')) imgSrc = e.target.querySelector('img').src;
                if(imgSrc) {
                    const overlay = document.getElementById('zoom-overlay');
                    const overlayImg = document.getElementById('zoom-overlay-img');
                    overlayImg.src = imgSrc.replace('image_128', 'image_1024').replace('image_256', 'image_1024');
                    overlay.style.display = 'flex';
                }
            } else if (e.target.id === 'zoom-overlay' || e.target.id === 'zoom-overlay-img') {
                document.getElementById('zoom-overlay').style.display = 'none';
            }
        });

        const catalog = window.hydroblokCatalog;

        // DT8_HB_3D_PLACEMENT_PREVIEW_20261015_V1: geometry-only visualization. Product/BOM pricing remains from Odoo.
        const hbSceneCamera = {yaw:0.29,pitch:0.61,zoom:1,active:false,pointer:false,lastX:0,lastY:0,placementSerial:0};
        function hbSafeNum(n, fallback) { const val=Number(n);return Number.isFinite(val)?val:fallback; }
        function hbClamp(n,lo,hi){return Math.max(lo,Math.min(hi,n));}
        function hbSkuSize(sku,kind){
            const known={HBDSC:[8,8],HBRSN1616:[16,16],HBRSN1628:[16,28],
                HBRDWSN3216:[32,16],HBRBHSN1622:[16,22],HBRDASN3226:[32,26],
                HBSBM:[17,17],HBSBL:[22,22],HBDBM:[17,17],HBDBL:[22,22]};
            return known[sku]||((kind==='bench')?[17,17]:[16,16]);
        }
        function hbPositionPanels(){
            ['niche','bench'].forEach(function(kind) {
                const container=document.getElementById(kind+'_container');
                if(!container)return;
                Array.from(container.querySelectorAll('select.accessory-select')).forEach(function(choice){
                    let panel=choice.nextElementSibling;
                    if(!panel || !panel.classList.contains('hb-place-panel')) {
                        panel=document.createElement('div');
                        panel.className='hb-place-panel d-print-none d-none';
                        const groupName='hbplacement'+(++hbSceneCamera.placementSerial);
                        panel.innerHTML='<div class="small fw-semibold mb-1">Position in shower</div>'+
                          '<div class="hb-place-wall" role="group" aria-label="Wall placement">'+
                          '<label><input type="radio" name="'+groupName+'" value="back" checked="checked"/>Back wall</label>'+
                          '<label><input type="radio" name="'+groupName+'" value="left"/>Left wall</label>'+
                          '<label><input type="radio" name="'+groupName+'" value="right"/>Right wall</label></div>'+
                          '<div class="hb-place-dims">'+
                          '<label>Along wall (in)<input type="number" min="0" step="1" class="form-control form-control-sm hb-place-along" value="12"/></label>'+
                          '<label>'+ (kind==='bench'?'Seat height (in)':'Bottom height (in)')+
                          '<input type="number" min="0" step="1" class="form-control form-control-sm hb-place-up" value="'+(kind==='bench'?'18':'42')+'"/></label></div>';
                        choice.insertAdjacentElement('afterend',panel);
                        panel.addEventListener('change',function(event){
                            if(event.target && event.target.type==='radio'){
                                const along=panel.querySelector('.hb-place-along');
                                const direction=panel.querySelector('input[type=radio]:checked').value;
                                const length=(direction==='back')?getVal('pan_w'):getVal('pan_d');
                                along.value=Math.max(0,Math.round((length-hbSkuSize(choice.value,kind)[0])/2));
                            }
                            calculateEngine();
                        });
                    }
                    const present=choice.value!=='none';
                    panel.classList.toggle('d-none',!present);
                    if(present && panel.dataset.currentSku!==choice.value){
                        const dir=panel.querySelector('input[type=radio]:checked').value;
                        const length=dir==='back'?getVal('pan_w'):getVal('pan_d');
                        panel.querySelector('.hb-place-along').value=Math.max(0,Math.round((length-hbSkuSize(choice.value,kind)[0])/2));
                        panel.dataset.currentSku=choice.value;
                    }
                });
            });
        }
        function hbSceneObjects(){
            const w=getVal('pan_w'),d=getVal('pan_d');
            let arr=[];
            ['niche','bench'].forEach(function(kind){
                const container=document.getElementById(kind+'_container');
                if(!container)return;
                Array.from(container.querySelectorAll('select.accessory-select')).forEach(function(sel){
                    if(sel.value==='none')return;
                    const panel=sel.nextElementSibling;
                    if(!panel||!panel.classList.contains('hb-place-panel'))return;
                    const wall=panel.querySelector('input[type=radio]:checked').value;
                    const size=hbSkuSize(sel.value,kind);
                    const max=(wall==='back'?w:d)-size[0];
                    arr.push({sku:sel.value,kind:kind,wall:wall,
                        along:hbClamp(hbSafeNum(panel.querySelector('.hb-place-along').value,0),0,Math.max(0,max)),
                        z:Math.max(0,hbSafeNum(panel.querySelector('.hb-place-up').value,kind==='bench'?18:42)),
                        pw:size[0],ph:size[1]});
                });
            });
            return arr;
        }
        function hbShowPreview(use3d) {
            hbSceneCamera.active=Boolean(use3d);
            const two=document.getElementById('canvas_container'),three=document.getElementById('hb_3d_container');
            const b2=document.getElementById('hb_show_plan_2d'),b3=document.getElementById('hb_show_plan_3d');
            if(two)two.classList.toggle('d-none',use3d);
            if(three)three.classList.toggle('d-none',!use3d);
            if(b2){b2.setAttribute('aria-pressed',String(!use3d));b2.className='btn btn-'+(use3d?'outline-success':'success')+' px-3';}
            if(b3){b3.setAttribute('aria-pressed',String(use3d));b3.className='btn btn-'+(use3d?'success':'outline-success')+' px-3';}
            if(use3d)hbRender3D();
        }
        function hbDraw2DLocationPins(){
            const canvas=document.getElementById('floorCanvas');
            if(!canvas)return;
            const w=getVal('pan_w'),d=getVal('pan_d');
            if(!(w>0&&d>0))return;
            const ctx=canvas.getContext('2d');const scale=700/w;
            const places=hbSceneObjects();
            ctx.save();ctx.setTransform(1,0,0,1,0,0);
            places.forEach(function(o,i){
                const along=o.along+o.pw/2;
                let x=o.wall==='back'?along:o.wall==='left'?0:w;
                let y=o.wall==='back'?0:along;
                x=50+x*scale;y=50+y*scale;
                ctx.beginPath();ctx.arc(x,y,10,0,Math.PI*2);
                ctx.fillStyle=o.kind==='bench'?'#936a45':'#355f41';ctx.fill();
                ctx.strokeStyle='#ffffff';ctx.lineWidth=2;ctx.stroke();
                ctx.fillStyle='#fff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 10px Arial';
                ctx.fillText(o.kind==='bench'?'B':'N',x,y);
            });
            ctx.restore();
        }
        function hbRender3D(){
            const canvas=document.getElementById('hb_3d_canvas');if(!canvas)return;
            const ctx=canvas.getContext('2d'),cw=canvas.width,ch=canvas.height;
            const W=getVal('pan_w'),D=getVal('pan_d');
            ctx.clearRect(0,0,cw,ch);
            const background=ctx.createLinearGradient(0,0,0,ch);
            background.addColorStop(0,'#fbfcfa');background.addColorStop(1,'#e7eee9');
            ctx.fillStyle=background;ctx.fillRect(0,0,cw,ch);
            if(!(W>0&&D>0&&W<=240&&D<=240))return;
            const H=hbClamp(Math.max(72,...wallData.slice(0,3).map(function(w){return hbSafeNum(w.h,96);})),72,144);
            const pitch=hbSceneCamera.pitch,yaw=hbSceneCamera.yaw;
            const scale=hbSceneCamera.zoom*Math.min(690/(W+D+25),460/(H*0.88+Math.max(W,D)*0.52));
            function project(pt){
                const xx=pt[0]-W/2,yy=pt[1]-D/2,zz=pt[2]-H*0.43;
                const u=xx*Math.cos(yaw)-yy*Math.sin(yaw);
                const v=xx*Math.sin(yaw)+yy*Math.cos(yaw);
                return [cw/2+u*scale,ch*0.54+(v*Math.sin(pitch)-zz*Math.cos(pitch))*scale];
            }
            function path3(points,fill,stroke,width) {
                if(!points.length)return;
                ctx.beginPath();
                points.forEach(function(p,i){const xy=project(p);if(i)ctx.lineTo(xy[0],xy[1]);else ctx.moveTo(xy[0],xy[1]);});
                ctx.closePath();
                if(fill){ctx.fillStyle=fill;ctx.fill();}
                if(stroke){ctx.lineWidth=width||1.4;ctx.strokeStyle=stroke;ctx.stroke();}
            }
            function line3(a,b,stroke,width){
                const aa=project(a),bb=project(b);ctx.beginPath();ctx.moveTo(aa[0],aa[1]);ctx.lineTo(bb[0],bb[1]);
                ctx.strokeStyle=stroke;ctx.lineWidth=width||1;ctx.stroke();
            }
            function caption(at,label,fill){
                const xy=project(at);ctx.font='600 12px Arial';ctx.fillStyle=fill||'#355548';ctx.textAlign='center';
                ctx.fillText(label,xy[0],xy[1]);
            }
            // Show the base, waterproofed wall planes and measured tile-grid.
            path3([[0,0,0],[W,0,0],[W,D,0],[0,D,0]],'#d9e7e2','#849a90',1.5);
            for(let x=12;x<W;x+=12)line3([x,0,.1],[x,D,.1],'#bbd0c5',0.6);
            for(let y=12;y<D;y+=12)line3([0,y,.1],[W,y,.1],'#bbd0c5',0.6);
            path3([[0,0,0],[W,0,0],[W,0,H],[0,0,H]],'rgba(233,242,231,.89)','#738e7e',1.7);
            path3([[0,D,0],[0,0,0],[0,0,H],[0,D,H]],'rgba(235,242,239,.67)','#829b91',1.5);
            path3([[W,0,0],[W,D,0],[W,D,H],[W,0,H]],'rgba(240,246,241,.54)','#829b91',1.5);
            for(let z=24;z<H;z+=24){line3([0,0,z],[W,0,z],'rgba(113,151,123,.26)',0.8);
                line3([0,0,z],[0,D,z],'rgba(113,151,123,.24)',0.8);
                line3([W,0,z],[W,D,z],'rgba(113,151,123,.20)',0.8);}
            const placed=hbSceneObjects();
            placed.forEach(function(o){
                const z=hbClamp(o.z,2,H-5),ww=Math.min(o.pw,o.wall==='back'?W:D);
                const extent=o.kind==='bench'?12:0.5;
                if(o.kind==='bench'||o.sku==='HBDSC'){
                    const depth=o.kind==='bench'?14:7;
                    const top=o.kind==='bench'?z:z+3;
                    let poly;
                    if(o.wall==='back')poly=[[o.along,0,top],[o.along+ww,0,top],[o.along+ww,depth,top],[o.along,depth,top]];
                    else if(o.wall==='left')poly=[[0,o.along,top],[depth,o.along,top],[depth,o.along+ww,top],[0,o.along+ww,top]];
                    else poly=[[W,o.along,top],[W-depth,o.along,top],[W-depth,o.along+ww,top],[W,o.along+ww,top]];
                    path3(poly,o.kind==='bench'?'#beac96':'#c9dec7','#5b7863',2);
                    const pt=poly[2];caption([pt[0],pt[1],top+6],o.kind==='bench'?'Bench':'Corner shelf','#35443b');
                } else {
                    const top=hbClamp(z+o.ph,z+3,H-2);
                    let pts,inner;
                    const x=o.along,xe=o.along+ww;
                    if(o.wall==='back'){pts=[[x,.75,z],[xe,.75,z],[xe,.75,top],[x,.75,top]];
                        inner=[[x+1,.95,z+1],[xe-1,.95,z+1],[xe-1,.95,top-1],[x+1,.95,top-1]];}
                    else if(o.wall==='left'){pts=[[.75,x,z],[.75,xe,z],[.75,xe,top],[.75,x,top]];
                        inner=[[.9,x+1,z+1],[.9,xe-1,z+1],[.9,xe-1,top-1],[.9,x+1,top-1]];}
                    else{pts=[[W-.75,x,z],[W-.75,xe,z],[W-.75,xe,top],[W-.75,x,top]];
                        inner=[[W-.9,x+1,z+1],[W-.9,xe-1,z+1],[W-.9,xe-1,top-1],[W-.9,x+1,top-1]];}
                    path3(pts,'#839b88','#3b644b',2.6);
                    path3(inner,'#354f41','#b5d4bb',1);
                    const p=pts[2];caption([p[0],p[1],p[2]+6],'Niche','#375340');
                }
            });
            // Drain is drawn from the same controls as the 2D plan.
            const drain=getStr('drain_type'),lin=getStr('entry_style')==='bf'?'entry':getStr('linear_loc');
            if(drain.indexOf('linear')===0){
                let da,db;
                if(lin==='side'){da=[2,Math.max(2,D/2-28),1];db=[2,Math.min(D-2,D/2+28),1];}
                else if(lin==='entry'){da=[Math.max(2,W/2-28),D-2,1];db=[Math.min(W-2,W/2+28),D-2,1];}
                else if(lin==='center_double'){da=[Math.max(2,W/2-28),D/2,1];db=[Math.min(W-2,W/2+28),D/2,1];}
                else {da=[Math.max(2,W/2-28),2,1];db=[Math.min(W-2,W/2+28),2,1];}
                line3(da,db,'#3d5149',5);
                caption([W/2,D/2,1.5],'Linear drain','#34493c');
            } else {
                let dx=W/2,dy=D/2;
                if(drain==='custom'){dx=getVal('custom_x');dy=getVal('custom_y');}
                else if(drain==='offset'){if(W>=D)dx=12;else dy=12;}
                const center=project([hbClamp(dx,0,W),hbClamp(dy,0,D),1.1]);
                ctx.beginPath();ctx.ellipse(center[0],center[1],Math.max(4,scale*2.6),Math.max(3,scale*1.3),0,0,Math.PI*2);
                ctx.fillStyle='#51675c';ctx.fill();ctx.lineWidth=1.5;ctx.strokeStyle='#fff';ctx.stroke();
            }
            // A curb is physical and is only rendered for a step-in entry.
            const entry=hbClamp(getVal('entry_w')||W,0,W),position=getStr('hb_entry_position');
            const ex=position==='left'?0:position==='right'?W-entry:(W-entry)/2;
            if(getStr('entry_style')==='bf'){
                line3([ex,D,.75],[ex+entry,D,.75],'#2999a3',5);
                caption([ex+entry/2,D+6,1],'Curbless entry','#206e75');
            } else {
                const curbH=getStr('curb_style')==='mini'?2:4;
                path3([[ex,D-2,curbH],[ex+entry,D-2,curbH],[ex+entry,D+2,curbH],[ex,D+2,curbH]],
                    '#c7cfca','#6b8377',1.5);
                path3([[ex,D+2,0],[ex+entry,D+2,0],[ex+entry,D+2,curbH],[ex,D+2,curbH]],
                    '#92a598','#5a7162',1.4);
                caption([ex+entry/2,D+6,curbH+3],getStr('curb_style')==='mini'?'Mini curb':'Shower curb','#354c40');
            }
            caption([W/2,0,H+8],'BACK WALL '+Math.round(W)+'″','#426347');
            caption([W/2,D+16,0],'FRONT / ENTRY','#53776a');
            const note='Shower '+W+'″ × '+D+'″  |  Wall height approx. '+Math.round(H)+'″';
            ctx.textAlign='left';ctx.fillStyle='#28483c';ctx.font='600 15px Arial';ctx.fillText(note,24,31);
            ctx.font='12px Arial';ctx.fillStyle='#61756b';
            if(wallData.length>3)ctx.fillText('Additional wall segments are in the material estimate, not this 3-wall preview.',24,ch-20);
            else if(wallData.slice(0,3).some(function(w,i){return Math.abs(w.w-(i===1?W:D))>0.5;}))
                ctx.fillText('Edited wall widths differ from the footprint; check wall quantities separately.',24,ch-20);
        }
        const hbPlan2DButton=document.getElementById('hb_show_plan_2d');
        const hbPlan3DButton=document.getElementById('hb_show_plan_3d');
        if(hbPlan2DButton)hbPlan2DButton.addEventListener('click',function(){hbShowPreview(false);});
        if(hbPlan3DButton)hbPlan3DButton.addEventListener('click',function(){hbShowPreview(true);});
        const hb3Canvas=document.getElementById('hb_3d_canvas');
        if(hb3Canvas){
            hb3Canvas.addEventListener('pointerdown',function(e){
                hbSceneCamera.pointer=true;hbSceneCamera.lastX=e.clientX;hbSceneCamera.lastY=e.clientY;
                hb3Canvas.style.cursor='grabbing';hb3Canvas.setPointerCapture(e.pointerId);
            });
            hb3Canvas.addEventListener('pointermove',function(e){
                if(!hbSceneCamera.pointer)return;
                hbSceneCamera.yaw+=(e.clientX-hbSceneCamera.lastX)*0.009;
                hbSceneCamera.pitch=hbClamp(hbSceneCamera.pitch+(e.clientY-hbSceneCamera.lastY)*0.006,0.27,1.2);
                hbSceneCamera.lastX=e.clientX;hbSceneCamera.lastY=e.clientY;hbRender3D();
            });
            ['pointerup','pointercancel','lostpointercapture'].forEach(function(t){
                hb3Canvas.addEventListener(t,function(){hbSceneCamera.pointer=false;hb3Canvas.style.cursor='grab';});
            });
            hb3Canvas.addEventListener('keydown',function(e){
                if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();hbSceneCamera.yaw+=(e.key==='ArrowLeft'?-0.16:0.16);hbRender3D();}
            });
        }
        const hbReset3D=document.getElementById('hb_3d_reset');
        if(hbReset3D)hbReset3D.addEventListener('click',function(){hbSceneCamera.yaw=0.29;hbSceneCamera.pitch=0.61;hbSceneCamera.zoom=1;hbRender3D();});
        const hbZoomIn=document.getElementById('hb_3d_zoom_in');
        const hbZoomOut=document.getElementById('hb_3d_zoom_out');
        if(hbZoomIn)hbZoomIn.addEventListener('click',function(){hbSceneCamera.zoom=hbClamp(hbSceneCamera.zoom*1.16,0.65,1.75);hbRender3D();});
        if(hbZoomOut)hbZoomOut.addEventListener('click',function(){hbSceneCamera.zoom=hbClamp(hbSceneCamera.zoom/1.16,0.65,1.75);hbRender3D();});

        // DT8_HB_DIAMOND_CADDY_SELECTOR_RUNTIME_20261015_V1: ensure corner caddy remains selectable even if frontend strips a late option.
        const hbNicheSelect = document.querySelector('#niche_container select');
        if (hbNicheSelect && !Array.from(hbNicheSelect.options).some(function(o){return o.value === 'HBDSC';})) {
            const hbDiamondOption = document.createElement('option');
            hbDiamondOption.value = 'HBDSC';
            hbDiamondOption.textContent = 'Diamond Shampoo Caddy 8" x 8"';
            hbNicheSelect.appendChild(hbDiamondOption);
        }

        // DT8_HB_OPTIONAL_FULL_CATALOGUE_20261015_V1: catalogue extras use live product IDs and guest/dealer-specific pricing.
        const hbOptionalSelections = Object.create(null);
        const hbOptionalNames = Object.create(null);
        const hbOptionalDirectory = document.getElementById('hb_optional_directory');
        if (hbOptionalDirectory) {
            Array.from(hbOptionalDirectory.options).forEach(function(option) {
                const sku = option.value;
                if (!sku || !catalog[sku] || !catalog[sku].id || !(Number(catalog[sku].price) > 0)) return;
                const description = option.textContent.trim() || sku;
                const cleanName = description.indexOf('['+sku+'] ')===0 ? description.slice(sku.length+3) : description;
                hbOptionalNames[sku] = cleanName;
                if (catalog[sku].name === sku) catalog[sku].name = cleanName;
            });
        }
        function hbRefreshOptionalChoices() {
            const sel = document.getElementById('hb_optional_select');
            const search = document.getElementById('hb_optional_search');
            if (!sel) return;
            const previous = sel.value;
            const term = ((search && search.value) || '').trim().toLowerCase();
            sel.replaceChildren();
            const placeholder = document.createElement('option');
            placeholder.value = '';
            placeholder.textContent = 'Select an item';
            sel.appendChild(placeholder);
            Object.keys(hbOptionalNames).sort().forEach(function(sku) {
                const label = hbOptionalNames[sku];
                if (term && (sku + ' ' + label).toLowerCase().indexOf(term) < 0) return;
                const option = document.createElement('option');
                option.value = sku;
                option.textContent = sku + ' — ' + label + ' · $' + Number(catalog[sku].price).toFixed(2);
                sel.appendChild(option);
            });
            if (Array.from(sel.options).some(function(option){return option.value === previous;})) sel.value = previous;
        }
        function hbRenderOptionalSelections() {
            const holder = document.getElementById('hb_optional_rows');
            if (!holder) return;
            holder.replaceChildren();
            Object.keys(hbOptionalSelections).sort().forEach(function(sku) {
                const qty = hbOptionalSelections[sku];
                if (!(qty > 0)) return;
                const row = document.createElement('div');
                row.className = 'd-flex align-items-center justify-content-between gap-2 py-2 border-bottom';
                const desc = document.createElement('span');
                desc.className = 'small';
                desc.textContent = qty + ' × ' + sku + ' — ' + (hbOptionalNames[sku] || (catalog[sku] && catalog[sku].name) || sku);
                const remove = document.createElement('button');
                remove.type = 'button';
                remove.className = 'btn btn-sm btn-outline-secondary';
                remove.textContent = 'Remove';
                remove.setAttribute('aria-label', 'Remove extra ' + sku);
                remove.addEventListener('click', function(){
                    delete hbOptionalSelections[sku];
                    hbRenderOptionalSelections();
                    calculateEngine();
                });
                row.appendChild(desc);
                row.appendChild(remove);
                holder.appendChild(row);
            });
        }
        const hbOptionalSearch = document.getElementById('hb_optional_search');
        if (hbOptionalSearch) hbOptionalSearch.addEventListener('input', hbRefreshOptionalChoices);
        const hbOptionalAdd = document.getElementById('hb_optional_add');
        if (hbOptionalAdd) hbOptionalAdd.addEventListener('click', function() {
            const sel = document.getElementById('hb_optional_select');
            const quantity = document.getElementById('hb_optional_qty');
            const sku = sel && sel.value;
            const qty = Math.floor(Number(quantity && quantity.value));
            if (!sku || !catalog[sku] || !catalog[sku].id || !Number.isFinite(qty) || qty < 1) return;
            hbOptionalSelections[sku] = (hbOptionalSelections[sku] || 0) + qty;
            hbRenderOptionalSelections();
            calculateEngine();
        });
        hbRefreshOptionalChoices();

        let ewEl = document.getElementById('entry_w');
        if(ewEl) {
            ewEl.addEventListener('blur', function() {
                let pw = parseFloat(document.getElementById('pan_w').value) || 0;
                let ew = parseFloat(this.value);
                if (isNaN(ew) || ew <= 0 || ew > pw) this.value = pw;
                calculateEngine();
            });
        }
        let pwEl = document.getElementById('pan_w');
        if(pwEl) {
            pwEl.addEventListener('blur', function() {
                let pw = parseFloat(this.value) || 0;
                let ew = parseFloat(document.getElementById('entry_w').value) || 0;
                if (ew > pw || isNaN(ew) || ew <= 0) { document.getElementById('entry_w').value = pw; }
                calculateEngine();
            });
        }

        // Live-update the core footprint/custom-drain measurements while typing.
        // Debounced to avoid repeatedly running the full shower engine on every keystroke.
        let liveCalcTimer = null;
        function scheduleLiveCalculation() {
            if (liveCalcTimer) clearTimeout(liveCalcTimer);
            liveCalcTimer = setTimeout(function() { calculateEngine(); }, 300);
        }
        ['pan_w', 'pan_d', 'entry_w', 'custom_x', 'custom_y'].forEach(function(id) {
            const el = document.getElementById(id);
            if (el) el.addEventListener('input', scheduleLiveCalculation);
        });

        function renderWallsUI() {
            const container = document.getElementById('dynamic_walls_container');
            const printContainer = document.getElementById('print_walls_container');
            if(!container || !printContainer) return;
            container.innerHTML = ''; printContainer.innerHTML = '';

            wallData.forEach(function(wall, index) {
                container.innerHTML += `
                    <div class="row g-2 mb-2 align-items-end wall-segment-row" data-id="${wall.id}">
                        <div class="col-md-4 col-4">
                            <label class="form-label text-muted small mb-0">Wall Name</label>
                            <input type="text" class="form-control form-control-sm wall-name" value="${wall.name}"/>
                        </div>
                        <div class="col-md-3 col-3">
                            <label class="form-label text-muted small mb-0">Width (in)</label>
                            <input type="number" class="form-control form-control-sm wall-w" value="${wall.w}" min="0"/>
                        </div>
                        <div class="col-md-3 col-3">
                            <label class="form-label text-muted small mb-0">Height (in)</label>
                            <input type="number" class="form-control form-control-sm wall-h" value="${wall.h}" min="0"/>
                        </div>
                        <div class="col-md-2 col-2 text-end">
                            <button type="button" class="btn btn-sm btn-outline-danger remove-wall-btn w-100" tabindex="-1" ${wallData.length <= 1 ? 'disabled' : ''}><i class="fa fa-trash"></i></button>
                        </div>
                    </div>
                `;
                printContainer.innerHTML += `
                    <div class="d-flex justify-content-between align-items-center border-bottom py-1" style="font-size: 9.5pt;">
                        <strong class="hb-green" style="width: 140px;">${wall.name}</strong>
                        <span class="text-muted text-start" style="flex: 1;">Width: <strong class="text-dark">${wall.w}"</strong></span>
                        <span class="text-muted text-start" style="flex: 1;">Height: <strong class="text-dark">${wall.h}"</strong></span>
                    </div>
                `;
            });

            container.querySelectorAll('.wall-name, .wall-w, .wall-h').forEach(function(input) { input.addEventListener('change', syncWallsAndCalculate); });
            container.querySelectorAll('.remove-wall-btn').forEach(function(btn, index) {
                btn.addEventListener('click', function() { wallData.splice(index, 1); renderWallsUI(); calculateEngine(); });
            });
        }

        function syncWallsAndCalculate() {
            wallData = Array.from(document.querySelectorAll('.wall-segment-row')).map(function(row) {
                return {
                    id: row.getAttribute('data-id'), name: row.querySelector('.wall-name').value || 'Wall',
                    w: parseFloat(row.querySelector('.wall-w').value) || 0, h: parseFloat(row.querySelector('.wall-h').value) || 0
                };
            });
            renderWallsUI(); calculateEngine();
        }

        let addWallBtn = document.getElementById('add_wall_btn');
        if (addWallBtn) {
            addWallBtn.addEventListener('click', function() {
                wallCounter++; let defaultH = wallData.length > 0 ? wallData[wallData.length - 1].h : 96;
                wallData.push({ id: wallCounter, name: 'Custom Wall', w: 36, h: defaultH });
                renderWallsUI(); calculateEngine();
            });
        }

        let esEl = document.getElementById('entry_style'); if(esEl) esEl.addEventListener('change', calculateEngine);
        let dtEl = document.getElementById('drain_type'); if(dtEl) dtEl.addEventListener('change', calculateEngine);
        let llEl = document.getElementById('linear_loc'); if(llEl) llEl.addEventListener('change', calculateEngine);
        let ltEl = document.getElementById('linear_trim'); if(ltEl) ltEl.addEventListener('change', calculateEngine);
        let btEl = document.getElementById('board_thick'); if(btEl) btEl.addEventListener('change', calculateEngine);

        document.querySelectorAll('.wallboard-toggle').forEach(function(el) {
            el.addEventListener('change', calculateEngine);
        });

        window.addAccessoryDropdown = function(type) {
            const container = document.getElementById(type + '_container');
            if (!container) return;
            const selects = container.querySelectorAll('select');
            if (selects.length >= 6) return; 
            const clone = selects[0].cloneNode(true);
            clone.value = 'none'; clone.classList.add('mt-2'); 
            clone.addEventListener('change', calculateEngine); 
            container.appendChild(clone); calculateEngine();
        };

        let anBtn = document.getElementById('add_niche_btn'); if(anBtn) anBtn.addEventListener('click', function() { window.addAccessoryDropdown('niche'); });
        let abBtn = document.getElementById('add_bench_btn'); if(abBtn) abBtn.addEventListener('click', function() { window.addAccessoryDropdown('bench'); });

        function drawFloorPlan(options) {
            const panW = options.panW; const panD = options.panD; const entryW = options.entryW; const activeFormat = options.activeFormat;
            const cX = options.cX; const cY = options.cY; const linLoc = options.linLoc; const isBarrierFree = options.isBarrierFree;
            const baseW = options.baseW; const baseR = options.baseR; const panQty = options.panQty; const sideExtQty = options.sideExtQty;
            const trimStyle = options.trimStyle; const bestPanConfig = options.bestPanConfig; const hasExtensions = options.hasExtensions;

            const canvas = document.getElementById('floorCanvas');
            if(!canvas) return;
            const ctx = canvas.getContext('2d');
            if (panW <= 0 || panD <= 0) { ctx.clearRect(0, 0, canvas.width, canvas.height); return; }

            canvas.width = 800; const padding = 50; const availableW = canvas.width - (padding * 2);
            const scale = availableW / panW; const drawW = availableW; const drawH = panD * scale;
            canvas.height = drawH + (padding * 2);
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = '#3A3D42'; ctx.font = "bold 16px Arial"; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
            ctx.fillText("Pan Width: " + panW + '"', canvas.width / 2, padding / 2);
            ctx.save(); ctx.translate(padding / 2, canvas.height / 2); ctx.rotate(-Math.PI / 2); ctx.fillText("Pan Depth: " + panD + '"', 0, 0); ctx.restore();
            ctx.translate(padding, padding);
            ctx.fillStyle = 'rgba(91, 158, 49, 0.15)'; ctx.fillRect(0, 0, drawW, drawH);

            let drawPanW = 0; let drawPanH = 0; let pX = 0; let pY = 0;

            if (activeFormat.includes('linear')) {
                let reqDrainEdge = (linLoc === 'back' || linLoc === 'entry' || linLoc === 'center_double') ? panW : panD;
                let reqRun = (linLoc === 'back' || linLoc === 'entry' || linLoc === 'center_double') ? (linLoc === 'center_double' ? panD/2 : panD) : panW;
                let physicalDrainEdge = Math.min(panQty * baseW, reqDrainEdge);
                if (sideExtQty > 0) physicalDrainEdge = baseW; 
                let physicalRun = Math.min(baseR, reqRun);

                if (linLoc === 'back') { drawPanW = physicalDrainEdge * scale; drawPanH = physicalRun * scale; pX = (drawW - drawPanW) / 2; pY = 0; }
                else if (linLoc === 'side') { drawPanW = physicalRun * scale; drawPanH = physicalDrainEdge * scale; pX = 0; pY = (drawH - drawPanH) / 2; }
                else if (linLoc === 'entry') { drawPanW = physicalDrainEdge * scale; drawPanH = physicalRun * scale; pX = (drawW - drawPanW) / 2; pY = drawH - drawPanH; }
                else if (linLoc === 'center_double') { drawPanW = physicalDrainEdge * scale; drawPanH = physicalRun * scale; pX = (drawW - drawPanW) / 2; }
            } else {
                if (bestPanConfig && bestPanConfig.opt) {
                    let opt = bestPanConfig.opt;
                    let startX = cX - opt.dx1; let endX = cX + opt.dx2; let startY = cY - opt.dy1; let endY = cY + opt.dy2;
                    pX = Math.max(0, startX) * scale; pY = Math.max(0, startY) * scale;
                    drawPanW = (Math.min(panW, endX) - Math.max(0, startX)) * scale;
                    drawPanH = (Math.min(panD, endY) - Math.max(0, startY)) * scale;
                }
            }

            if (activeFormat.includes('linear') && linLoc === 'center_double') {
                ctx.clearRect(pX, (drawH/2) - drawPanH, drawPanW, drawPanH); ctx.fillStyle = '#f0f3f1'; ctx.fillRect(pX, (drawH/2) - drawPanH, drawPanW, drawPanH);
                ctx.clearRect(pX, drawH/2, drawPanW, drawPanH); ctx.fillStyle = '#f0f3f1'; ctx.fillRect(pX, drawH/2, drawPanW, drawPanH);
            } else {
                ctx.clearRect(pX, pY, drawPanW, drawPanH); ctx.fillStyle = '#f0f3f1'; ctx.fillRect(pX, pY, drawPanW, drawPanH);
            }

            if (panQty > 1) {
                if (activeFormat.includes('linear') && bestPanConfig && bestPanConfig.sideExtQty === 0) {
                    ctx.strokeStyle = 'rgba(0,0,0,0.15)'; ctx.lineWidth = 2; ctx.setLineDash([5, 5]);
                    let singlePanEdgeScale = bestPanConfig.baseW * scale;
                    let numPansPerSide = (linLoc === 'center_double') ? panQty / 2 : panQty;

                    if (linLoc === 'side') {
                        for(let i=1; i<numPansPerSide; i++) {
                            let seamY = pY + (i * singlePanEdgeScale);
                            if (seamY < pY + drawPanH) { ctx.beginPath(); ctx.moveTo(pX, seamY); ctx.lineTo(pX + drawPanW, seamY); ctx.stroke(); }
                        }
                    } else if (linLoc === 'center_double') {
                        for(let i=1; i<numPansPerSide; i++) {
                            let seamX = pX + (i * singlePanEdgeScale);
                            if (seamX < pX + drawPanW) { ctx.beginPath(); ctx.moveTo(seamX, (drawH/2) - drawPanH); ctx.lineTo(seamX, (drawH/2) + drawPanH); ctx.stroke(); }
                        }
                    } else {
                        for(let i=1; i<numPansPerSide; i++) {
                            let seamX = pX + (i * singlePanEdgeScale);
                            if (seamX < pX + drawPanW) { ctx.beginPath(); ctx.moveTo(seamX, pY); ctx.lineTo(seamX, pY + drawPanH); ctx.stroke(); }
                        }
                    }
                    ctx.setLineDash([]);
                }
            }

            ctx.strokeStyle = '#5B9E31'; ctx.lineWidth = 2; ctx.setLineDash([6, 6]);
            if (activeFormat.includes('linear') && linLoc === 'center_double') {
                ctx.strokeRect(pX, (drawH/2) - drawPanH, drawPanW, drawPanH); ctx.strokeRect(pX, drawH/2, drawPanW, drawPanH);
            } else {
                ctx.strokeRect(pX, pY, drawPanW, drawPanH);
            }
            ctx.setLineDash([]);
            ctx.strokeStyle = 'rgba(91, 158, 49, 0.1)'; ctx.lineWidth = 1;
            for(let i=0; i<panW; i+=12) { ctx.beginPath(); ctx.moveTo(i*scale, 0); ctx.lineTo(i*scale, drawH); ctx.stroke(); }
            for(let i=0; i<panD; i+=12) { ctx.beginPath(); ctx.moveTo(0, i*scale); ctx.lineTo(drawW, i*scale); ctx.stroke(); }

            if (hasExtensions) {
                ctx.fillStyle = '#2d4f18'; ctx.font = "bold 12px Arial"; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
                if (activeFormat.includes('linear') && linLoc === 'center_double') {
                    if (Math.round(drawPanW) < Math.round(drawW)) {
                        let leftExtX = pX / 2; if (leftExtX < 20) leftExtX += 15; 
                        if (pX > 0) { ctx.save(); ctx.translate(leftExtX, drawH / 2); ctx.rotate(-Math.PI / 2); ctx.fillText("EXTENSION", 0, 0); ctx.restore(); }
                        let rightExtX = pX + drawPanW + (drawW - (pX + drawPanW))/2;
                        if (drawW - (pX + drawPanW) > 0) { ctx.save(); ctx.translate(rightExtX, drawH / 2); ctx.rotate(-Math.PI / 2); ctx.fillText("EXTENSION", 0, 0); ctx.restore(); }
                    }
                } else {
                    if (Math.round(drawPanH) < Math.round(drawH)) {
                        let topExtY = pY / 2; if ((activeFormat.includes('linear') && linLoc === 'back') && topExtY < 20) topExtY += 15;
                        if (pY > 0) { ctx.fillText("EXTENSION", drawW / 2, topExtY); }
                        let botExtY = pY + drawPanH + (drawH - (pY + drawPanH))/2;
                        if ((activeFormat.includes('linear') && linLoc === 'entry') && (drawH - botExtY) < 20) botExtY -= 15;
                        if (drawH - (pY + drawPanH) > 0) { ctx.fillText("EXTENSION", drawW / 2, botExtY); }
                    }
                    if (Math.round(drawPanW) < Math.round(drawW)) {
                        let leftExtX = pX / 2; if ((activeFormat.includes('linear') && linLoc === 'side') && leftExtX < 20) leftExtX += 15;
                        if (pX > 0) { ctx.save(); ctx.translate(leftExtX, drawH / 2); ctx.rotate(-Math.PI / 2); ctx.fillText("EXTENSION", 0, 0); ctx.restore(); }
                        let rightExtX = pX + drawPanW + (drawW - (pX + drawPanW))/2;
                        if (drawW - (pX + drawPanW) > 0) { ctx.save(); ctx.translate(rightExtX, drawH / 2); ctx.rotate(-Math.PI / 2); ctx.fillText("EXTENSION", 0, 0); ctx.restore(); }
                    }
                }
            }

            ctx.strokeStyle = '#3A3D42'; ctx.lineWidth = 4; ctx.strokeRect(0, 0, drawW, drawH);
            ctx.strokeStyle = '#5B9E31'; ctx.lineWidth = 2; ctx.fillStyle = '#5B9E31';

            if (activeFormat === 'center' || activeFormat === 'offset' || activeFormat === 'custom') {
                let drainPxX = cX * scale; let drainPxY = cY * scale; 
                if (drainPxX < 0) drainPxX = 0; if (drainPxX > drawW) drainPxX = drawW;
                if (drainPxY < 0) drainPxY = 0; if (drainPxY > drawH) drainPxY = drawH;
                ctx.beginPath(); ctx.arc(drainPxX, drainPxY, 8, 0, 2 * Math.PI); ctx.fill();
                ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(drainPxX, drainPxY); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(drawW, 0); ctx.lineTo(drainPxX, drainPxY); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(0, drawH); ctx.lineTo(drainPxX, drainPxY); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(drawW, drawH); ctx.lineTo(drainPxX, drainPxY); ctx.stroke();
            } else if (activeFormat.includes('linear')) {
                ctx.fillStyle = '#666'; 
                let dThickness = 5 * scale; let gap = (trimStyle === 'sight') ? (2 * scale) : 0;
                let reqDrainEdge = (linLoc === 'back' || linLoc === 'entry' || linLoc === 'center_double') ? panW : panD;
                let reqDrainQty = 1;
                if (reqDrainEdge > 73.5) reqDrainQty = Math.ceil((reqDrainEdge - 24) / 73.5);
                if (reqDrainQty < 1) reqDrainQty = 1;

                if (linLoc === 'back') {
                    let drainActualL = Math.min(drawW, (reqDrainQty * 73.5) * scale); let dStartX = (drawW / 2) - (drainActualL / 2);
                    ctx.fillRect(dStartX, gap, drainActualL, dThickness);
                    ctx.beginPath(); ctx.moveTo(drawW/2, drawH - (20*scale)); ctx.lineTo(drawW/2, gap + dThickness + (5*scale)); ctx.lineTo((drawW/2) - 10, gap + dThickness + (5*scale) + 10);
                    ctx.moveTo(drawW/2, gap + dThickness + (5*scale)); ctx.lineTo((drawW/2) + 10, gap + dThickness + (5*scale) + 10); ctx.stroke();
                } else if (linLoc === 'side') {
                    let drainActualL = Math.min(drawH, (reqDrainQty * 73.5) * scale); let dStartY = (drawH / 2) - (drainActualL / 2);
                    ctx.fillRect(gap, dStartY, dThickness, drainActualL);
                    ctx.beginPath(); ctx.moveTo(drawW - (20*scale), drawH/2); ctx.lineTo(gap + dThickness + (5*scale), drawH/2); ctx.lineTo(gap + dThickness + (5*scale) + 10, (drawH/2) - 10);
                    ctx.moveTo(gap + dThickness + (5*scale), drawH/2); ctx.lineTo(gap + dThickness + (5*scale) + 10, (drawH/2) + 10); ctx.stroke();
                } else if (linLoc === 'entry') {
                    let drainActualL = Math.min(drawW, (reqDrainQty * 73.5) * scale); let dStartX = (drawW / 2) - (drainActualL / 2);
                    let curbOffset = (isBarrierFree ? 0 : 4.5 * scale); let dStartY = drawH - curbOffset - dThickness - gap;
                    ctx.fillRect(dStartX, dStartY, drainActualL, dThickness);
                    ctx.beginPath(); ctx.moveTo(drawW/2, 20*scale); ctx.lineTo(drawW/2, dStartY - (5*scale)); ctx.lineTo((drawW/2) - 10, dStartY - (5*scale) - 10);
                    ctx.moveTo(drawW/2, dStartY - (5*scale)); ctx.lineTo((drawW/2) + 10, dStartY - (5*scale) - 10); ctx.stroke();
                } else if (linLoc === 'center_double') {
                    let drainActualL = Math.min(drawW, (reqDrainQty * 73.5) * scale); let dStartX = (drawW / 2) - (drainActualL / 2); let dStartY = (drawH / 2) - (dThickness / 2);
                    ctx.fillRect(dStartX, dStartY, drainActualL, dThickness);
                    ctx.beginPath(); ctx.moveTo(drawW/2, 10*scale); ctx.lineTo(drawW/2, dStartY - (5*scale)); ctx.lineTo((drawW/2) - 10, dStartY - (5*scale) - 10); ctx.moveTo(drawW/2, dStartY - (5*scale)); ctx.lineTo((drawW/2) + 10, dStartY - (5*scale) - 10); ctx.stroke();
                    ctx.beginPath(); ctx.moveTo(drawW/2, drawH - (10*scale)); ctx.lineTo(drawW/2, dStartY + dThickness + (5*scale)); ctx.lineTo((drawW/2) - 10, dStartY + dThickness + (5*scale) + 10); ctx.moveTo(drawW/2, dStartY + dThickness + (5*scale)); ctx.lineTo((drawW/2) + 10, dStartY + dThickness + (5*scale) + 10); ctx.stroke();
                }
            }

            if (entryW > 0) {
                const pxEntryW = entryW * scale; const position = getStr('hb_entry_position'); const entryStartX = position === 'left' ? 0 : (position === 'right' ? drawW - pxEntryW : (drawW - pxEntryW) / 2);
                if (isBarrierFree) {
                    ctx.strokeStyle = '#0d6efd'; ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(entryStartX, drawH); ctx.lineTo(entryStartX + pxEntryW, drawH); ctx.stroke();
                    ctx.fillStyle = 'rgba(255,255,255,0.85)'; ctx.fillRect(entryStartX + 10, drawH - 24, pxEntryW - 20, 20);
                    ctx.fillStyle = '#0d6efd'; ctx.font = "bold 14px Arial"; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText("Curbless Transition (" + entryW + "\")", entryStartX + pxEntryW/2, drawH - 14);
                } else {
                    const curbDepth = 4.5 * scale; ctx.fillStyle = '#dcdcdc'; ctx.fillRect(entryStartX, drawH - curbDepth, pxEntryW, curbDepth);
                    ctx.strokeStyle = '#3A3D42'; ctx.lineWidth = 2; ctx.strokeRect(entryStartX, drawH - curbDepth, pxEntryW, curbDepth);
                    ctx.fillStyle = '#333'; ctx.font = "bold 12px Arial"; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
                    let curbLabel = pxEntryW < 120 ? "Curb" : "Shower Curb Component (" + entryW + "\")"; ctx.fillText(curbLabel, entryStartX + pxEntryW/2, drawH - (curbDepth/2));
                }
            }
        }

        function drawWallVisualizer(walls, use3660, use4864, use4896) {
            const canvas = document.getElementById('wallCanvas'); if(!canvas) return; const ctx = canvas.getContext('2d');
            const gap = 8; const activeWalls = walls.filter(function(w) { return w.w > 0 && w.h > 0; });
            if (activeWalls.length === 0) { ctx.clearRect(0, 0, canvas.width, canvas.height); return; }

            const totalWidthInches = activeWalls.reduce(function(sum, wall) { return sum + wall.w; }, 0) + (gap * (activeWalls.length - 1)) + (gap * 2);
            const maxH = Math.max.apply(Math, activeWalls.map(function(w) { return w.h; }));
            const textSpaceInches = 15; const bottomSpaceInches = 2; const totalHeightInches = maxH + textSpaceInches + bottomSpaceInches;
            canvas.width = 1200; canvas.height = (totalHeightInches / totalWidthInches) * 1200; ctx.clearRect(0, 0, canvas.width, canvas.height);

            const scale = canvas.width / totalWidthInches; const yOffset = textSpaceInches * scale;

            function drawScrew(x, y) {
                ctx.beginPath(); ctx.arc(x, y, 0.8 * scale, 0, 2 * Math.PI); ctx.fillStyle = '#B0B5B9'; ctx.fill();
                ctx.lineWidth = 0.5; ctx.strokeStyle = '#555'; ctx.stroke();
                ctx.beginPath(); ctx.arc(x, y, 0.2 * scale, 0, 2 * Math.PI); ctx.fillStyle = '#333'; ctx.fill();
            }

            function drawWallSegment(startX, wallW, wallH, label) {
                const pxW = wallW * scale; const pxH = wallH * scale; const pxStartX = startX * scale;
                const maxPxH = maxH * scale; const pxStartY = yOffset + maxPxH - pxH; 

                ctx.fillStyle = '#e4e7e5'; ctx.fillRect(pxStartX, pxStartY, pxW, pxH);
                ctx.strokeStyle = '#3A3D42'; ctx.lineWidth = 3; ctx.strokeRect(pxStartX, pxStartY, pxW, pxH);

                const hSeams = []; const vSeams = []; const boards = [];

                for(let bx = 0; bx < wallW; ) {
                    let bW = 36;
                    if (use4896 || use4864) { if (wallW - bx > 36 || !use3660) bW = 48; }
                    const drawW = Math.min(bW, wallW - bx);

                    for(let by = 0; by < wallH; ) {
                        let bH = 60; let remH = wallH - by;
                        if (bW === 48) {
                            if (use4896 && (remH > 64 || !use4864)) bH = 96; else if (use4864) bH = 64; else bH = 96;
                        }
                        const drawH = Math.min(bH, wallH - by); boards.push({x: bx, y: by, w: drawW, h: drawH});
                        if (by + drawH < wallH) { hSeams.push({y: by + drawH, startX: bx, endX: bx + drawW}); }
                        by += bH;
                    }
                    if (bx + drawW < wallW) { vSeams.push({x: bx + drawW, startY: 0, endY: wallH}); }
                    bx += bW;
                }

                boards.forEach(function(b) {
                    const sx = pxStartX + (b.x * scale); const sy = pxStartY + pxH - (b.y * scale) - (b.h * scale);
                    const sw = b.w * scale; const sh = b.h * scale;

                    ctx.save(); ctx.beginPath(); ctx.rect(sx, sy, sw, sh); ctx.clip();
                    ctx.fillStyle = 'rgba(91, 158, 49, 0.12)'; ctx.font = "bold " + (3.5 * scale) + "px Arial"; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
                    const stepX = 25 * scale; const stepY = 18 * scale; const offsetX = ((b.x * 13) + (b.y * 7)) % stepX; const offsetY = ((b.x * 5) + (b.y * 11)) % stepY;
                    for (let px = sx - stepX + offsetX; px < sx + sw + stepX; px += stepX) {
                        for (let py = sy - stepY + offsetY; py < sy + sh + stepY; py += stepY) {
                            ctx.save(); ctx.translate(px, py); ctx.rotate(-Math.PI / 6); ctx.fillText("HYDRO-BLOK", 0, 0); ctx.restore();
                        }
                    }
                    ctx.restore();
                    ctx.strokeStyle = '#5B9E31'; ctx.lineWidth = 2; ctx.strokeRect(sx, sy, sw, sh);
                });

                const screwMap = new Set(); const finalScrews = [];
                function addS(x_in, y_in) {
                    if (y_in < 2) return; if (x_in < 1) x_in = 1; if (x_in > wallW - 1) x_in = wallW - 1; if (y_in > wallH - 1) y_in = wallH - 1;
                    const key = Math.round(x_in) + "," + Math.round(y_in);
                    if (!screwMap.has(key)) { screwMap.add(key); finalScrews.push({x: x_in, y: y_in}); }
                }

                const studs = []; for(let x=0; x<=wallW; x+=16) studs.push(x); if (studs[studs.length-1] !== wallW) studs.push(wallW);
                for (let cx of studs) { for (let cy = 12; cy < wallH; cy += 12) { addS(cx, cy); } addS(cx, wallH - 1); }
                hSeams.forEach(function(seam) { for (let cx of studs) { if (cx >= seam.startX && cx <= seam.endX) { addS(cx, seam.y); } } });
                vSeams.forEach(function(seam) { for (let cy = 12; cy < wallH; cy += 12) { addS(seam.x, cy); } addS(seam.x, wallH - 1); });

                for(let s of finalScrews) { const cx = pxStartX + (s.x * scale); const cy = pxStartY + pxH - (s.y * scale); drawScrew(cx, cy); }

                ctx.fillStyle = '#3A3D42'; let fontSize = 28; if (pxW < 220) fontSize = 22; if (pxW < 150) fontSize = 18;
                ctx.font = "bold " + fontSize + "px Arial"; ctx.textAlign = 'center'; ctx.fillText(label + " (" + wallW + "\")", pxStartX + (pxW/2), pxStartY - 15);
            }

            let currentStartX = gap;
            activeWalls.forEach(function(wall) { drawWallSegment(currentStartX, wall.w, wall.h, wall.name); currentStartX += wall.w + gap; });
        }

        function getBestPointPan(panW, panD, cX, cY, isOffsetMode) {
            let options = [];
            if (isOffsetMode) {
                options.push({sku: 'HBLPSP3672OD', w: 36, d: 72, dx1: 18, dx2: 18, dy1: 12, dy2: 60});
                options.push({sku: 'HBLPSP3672OD', w: 36, d: 72, dx1: 18, dx2: 18, dy1: 60, dy2: 12});
                options.push({sku: 'HBLPSP3672OD', w: 72, d: 36, dx1: 12, dx2: 60, dy1: 18, dy2: 18});
                options.push({sku: 'HBLPSP3672OD', w: 72, d: 36, dx1: 60, dx2: 12, dy1: 18, dy2: 18});
            } else {
                let centerSkus = ['HBLPSP3636', 'HBLPSP3648', 'HBLPSP4848', 'HBLPSP3660', 'HBLPSP4860', 'HBLPSP6060', 'HBLPSP3672', 'HBLPSP4872', 'HBLPSP4884', 'HBLPSP6072', 'HBLPSP6084', 'HBLPSP7272'];
                for (let s of centerSkus) {
                    let match = s.match(/(\d{2})(\d{2})/);
                    let w = parseInt(match[1]); let d = parseInt(match[2]);
                    options.push({sku: s, w: w, d: d, dx1: w/2, dx2: w/2, dy1: d/2, dy2: d/2});
                    if (w !== d) { options.push({sku: s, w: d, d: w, dx1: d/2, dx2: d/2, dy1: w/2, dy2: w/2}); }
                }
            }

            let bestPan = null; let minScore = Infinity;
            for (let opt of options) {
                let extL = Math.max(0, cX - opt.dx1); let extR = Math.max(0, (panW - cX) - opt.dx2);
                let extT = Math.max(0, cY - opt.dy1); let extB = Math.max(0, (panD - cY) - opt.dy2);

                if (extL <= 12 && extR <= 12 && extT <= 12 && extB <= 12) {
                    let baseAreaSqIn = opt.w * opt.d;
                    let covStartX = Math.max(0, cX - opt.dx1); let covEndX = Math.min(panW, cX + opt.dx2);
                    let covStartY = Math.max(0, cY - opt.dy1); let covEndY = Math.min(panD, cY + opt.dy2);
                    let covW = Math.max(0, covEndX - covStartX); let covH = Math.max(0, covEndY - covStartY);
                    let coveredAreaSqIn = covW * covH; let requiredExtAreaSqIn = (panW * panD) - coveredAreaSqIn;
                    let score = baseAreaSqIn + (requiredExtAreaSqIn * 1000);

                    if (score < minScore) {
                        minScore = score;
                        bestPan = { sku: opt.sku, requiresExt: requiredExtAreaSqIn > 0, uncoveredSqIn: requiredExtAreaSqIn, w: opt.w, d: opt.d, opt: opt };
                    }
                }
            }
            return bestPan;
        }

        function getBestLinearPan(reqW, reqD, isThin, loc) {
            let reqDrainEdge = (loc === 'back' || loc === 'entry' || loc === 'center_double') ? reqW : reqD;
            let reqRun = (loc === 'back' || loc === 'entry' || loc === 'center_double') ? (loc === 'center_double' ? reqD/2 : reqD) : reqW;
            if (reqRun > 72) return null; 

            let linearPans = isThin ?
                [{sku: 'HBTSSSP3660', w: 36, r: 60}, {sku: 'HBTSSSP6036', w: 60, r: 36}, {sku: 'HBTSSSP4872', w: 48, r: 72}, {sku: 'HBTSSSP7248', w: 72, r: 48}] :
                [{sku: 'HBSSSP3660', w: 36, r: 60}, {sku: 'HBSSSP6036', w: 60, r: 36}, {sku: 'HBSSSP4872', w: 48, r: 72}, {sku: 'HBSSSP7248', w: 72, r: 48}];
            let sideExtSku = isThin ? null : 'HBSSSP1872EXT'; 
            let best = null; let minCost = Infinity;

            for (let p of linearPans) {
                if (reqRun <= p.r) {
                    let qtyPansOnly = Math.ceil(reqDrainEdge / p.w);
                    let costA = qtyPansOnly * window.hydroblokCatalog[p.sku].price;
                    let optA = { sku: p.sku, panQty: qtyPansOnly, sideExtQty: 0, cost: costA, baseW: p.w, baseR: p.r };
                    let bestOpt = optA;

                    if (sideExtSku && p.w < reqDrainEdge) {
                        let remainingWidth = reqDrainEdge - p.w; let numSideExts = Math.ceil(remainingWidth / 18);
                        let costB = window.hydroblokCatalog[p.sku].price + (numSideExts * window.hydroblokCatalog[sideExtSku].price);
                        if (costB < costA) { bestOpt = { sku: p.sku, panQty: 1, sideExtQty: numSideExts, cost: costB, baseW: p.w, baseR: p.r }; }
                    }
                    if (bestOpt.cost < minCost) { minCost = bestOpt.cost; best = bestOpt; }
                }
            }
            return best;
        }

        function renderErrorState(msg) {
            const errorBox = document.getElementById('validation_error_box'); const errorText = document.getElementById('validation_error_text');
            const canvasCont = document.getElementById('canvas_container'); const bomBody = document.getElementById('bom_table_body');
            const gTotal = document.getElementById('grand_total'); const btn = document.getElementById('add_to_quote_btn'); const gallery = document.getElementById('foundation_gallery_container');
            if (errorBox && errorText) { errorBox.classList.remove('d-none'); errorText.innerHTML = msg; }
            if (canvasCont) canvasCont.classList.add('d-none'); const preview3d=document.getElementById('hb_3d_container'); if(preview3d)preview3d.classList.add('d-none'); if (bomBody) bomBody.innerHTML = '';
            if (gTotal) gTotal.innerText = '$0.00'; if (btn) btn.disabled = true; if (gallery) gallery.classList.add('d-none');
        }

        function clearErrorState() {
            const errorBox = document.getElementById('validation_error_box'); const canvasCont = document.getElementById('canvas_container'); const btn = document.getElementById('add_to_quote_btn');
            if (errorBox) errorBox.classList.add('d-none'); if (canvasCont) canvasCont.classList.toggle('d-none',hbSceneCamera.active); const preview3d=document.getElementById('hb_3d_container'); if(preview3d)preview3d.classList.toggle('d-none',!hbSceneCamera.active); if (btn) btn.disabled = false;
        }

        function calculateEngine() {
            try {
                clearErrorState(); let bom = {};
                const panW = getVal('pan_w'); const panD = getVal('pan_d');

        // DT8_HB_PRODUCTION_ENTRY_WIDTH_RESTORE_20261015_V1: full-width entry follows footprint changes; manually edited entry widths do not.
        if (panW > 0 && panW !== hbLastFootprint.w && hbEntryFollowsFootprint && hbEntryInput) hbEntryInput.value = String(panW);
        // DT8_HB_UX_VALIDATION_WALL_LINK_ENTRY_20261015_V1: keep standard three primary wall widths tied to footprint until individually changed.
        if (panW > 0 && panD > 0 && (panW !== hbLastFootprint.w || panD !== hbLastFootprint.d)) {
            let hbNeedsWallRefresh = false;
            [[0,'Left Wall',hbLastFootprint.d,panD],[1,'Back Wall',hbLastFootprint.w,panW],[2,'Right Wall',hbLastFootprint.d,panD]].forEach(function(spec) {
                const wall = wallData[spec[0]];
                if (wall && wall.name === spec[1] && Math.abs(wall.w - spec[2]) < 0.001 && Math.abs(wall.w - spec[3]) > 0.001) {
                    wall.w = spec[3]; hbNeedsWallRefresh = true;
                }
            });
            hbLastFootprint = {w:panW,d:panD};
            if (hbNeedsWallRefresh) renderWallsUI();
        }
        if (panW <= 0 || panD <= 0 || panW > 240 || panD > 240) {
            renderErrorState('Please enter a shower width and depth greater than zero and no more than 240 inches. For larger custom installations, contact our design team.');
            return;
        }
        // Narrow entrance widths are supported. Invalid intermediate input is not sent to the cart.

                let entryWidthEl = document.getElementById('entry_w'); let entryWidth = parseFloat(entryWidthEl.value);
                if (isNaN(entryWidth) || entryWidth <= 0 || entryWidth > panW) {
                    entryWidth = panW; if (document.activeElement !== entryWidthEl && entryWidthEl) entryWidthEl.value = panW;
                }

                let drainTypeEl = document.getElementById('drain_type'); let linLocEl = document.getElementById('linear_loc');
                let optLinearStd = document.getElementById('opt_linear_std'); let trimSelect = document.getElementById('linear_trim');

                let activeDrainType = drainTypeEl.value; const isLinear = activeDrainType.includes('linear');
                let activeLinLoc = linLocEl ? linLocEl.value : 'back'; // DT8_HB_DOUBLE_SLOPE_STATE_AND_OPTION_PRICE_20261015_V1
                const customX = getVal('custom_x'); const customY = getVal('custom_y');

                const customGroups = document.querySelectorAll('.custom-drain-group');
                const linPanel = document.getElementById('linear_panel');

                if (activeDrainType === 'custom') {
                    customGroups.forEach(function(el) { el.classList.remove('d-none'); });
                    if (linPanel) linPanel.classList.add('d-none');
                } else {
                    customGroups.forEach(function(el) { el.classList.add('d-none'); });
                    if (linPanel) { if (isLinear) linPanel.classList.remove('d-none'); else linPanel.classList.add('d-none'); }
                }

                const locCont = document.getElementById('linear_loc_container');
                const barrierHint = document.getElementById('barrier_linear_hint');
                const curbContainer = document.getElementById('curb_style_container');
                const isCurbless = getStr('entry_style') === 'bf';
                let isDoubleSlope = (activeLinLoc === 'center_double');

                if (curbContainer) curbContainer.classList.toggle('d-none', isCurbless);

                if (isCurbless) {
                    if (optLinearStd) {
                        optLinearStd.disabled = true; optLinearStd.style.display = 'none';
                        if (activeDrainType === 'linear_std') { drainTypeEl.value = 'linear_thin'; activeDrainType = 'linear_thin'; }
                    }
                } else { if (optLinearStd) { optLinearStd.disabled = false; optLinearStd.style.display = ''; } }

                if (isLinear) {
                    if (isDoubleSlope && trimSelect) {
                        trimSelect.value = 'sight'; if (trimSelect.parentElement) trimSelect.parentElement.classList.add('d-none'); 
                    } else if (trimSelect) {
                        if (trimSelect.parentElement && !isCurbless) trimSelect.parentElement.classList.remove('d-none'); 
                    }
                    if (isCurbless) {
                        if (linLocEl) { linLocEl.value = 'entry'; activeLinLoc = 'entry'; isDoubleSlope = false; if (locCont) locCont.classList.add('d-none'); }
                        if (trimSelect) { trimSelect.value = 'sight'; if (trimSelect.parentElement) trimSelect.parentElement.classList.add('d-none'); }
                        if (barrierHint) { barrierHint.innerHTML = '* Curbless linears <strong>must</strong> be placed at the entrance.'; barrierHint.classList.remove('d-none'); }
                    } else {
                        if (linLocEl && locCont) locCont.classList.remove('d-none'); if (barrierHint) barrierHint.classList.add('d-none');
                    }
                }

                let validationError = null; let bestPointPan = null; let cX = panW / 2; let cY = panD / 2;

                if (isLinear) {
                    let reqRun = (activeLinLoc === 'center_double') ? panD/2 : (activeLinLoc === 'side' ? panW : panD);
                    if (reqRun > 72) validationError = "⚠️ <strong>Shower Too Large:</strong> The water flow path is too long for a standard single-slope pan. Please reduce the size or select 'Center Area (Double Slope)' to split the water flow.";
                } else {
                    if (activeDrainType === 'offset') {
                        if (panW >= panD) { cX = 12; cY = panD / 2; } else { cX = panW / 2; cY = 12; }
                        bestPointPan = getBestPointPan(panW, panD, cX, cY, true);
                        if (!bestPointPan) validationError = "⚠️ <strong>Shower Too Large for Point Drain:</strong> This shower is too large to properly funnel water to an offset point drain. Please switch to a 'Linear Drain'.";
                    } else if (activeDrainType === 'center') {
                        bestPointPan = getBestPointPan(panW, panD, cX, cY, false);
                        if (!bestPointPan) validationError = "⚠️ <strong>Shower Too Large for Point Drain:</strong> This shower is too large to properly funnel water to a center circular drain. Please switch to a 'Linear Drain'.";
                    } else if (activeDrainType === 'custom') {
                        cX = customX; cY = customY; let minDist = Math.min(customX, panW - customX, customY, panD - customY);
                        if (minDist < 10) { validationError = "⚠️ <strong>Drain Too Close to Wall:</strong> Point drains need at least 10 inches of space from the walls to keep the floor properly sloped. Please move the drain inward, or switch to a 'Linear Drain'.";
                        } else {
                            bestPointPan = getBestPointPan(panW, panD, cX, cY, false);
                            let offsetCheck = getBestPointPan(panW, panD, cX, cY, true);
                            if (offsetCheck) { if (!bestPointPan || offsetCheck.uncoveredSqIn < bestPointPan.uncoveredSqIn) bestPointPan = offsetCheck; }
                            if (!bestPointPan) validationError = "⚠️ <strong>Shower Too Large for Point Drain:</strong> This shower is too large to properly funnel water to a single circular drain. Please switch to a 'Linear Drain'.";
                        }
                    }
                }

                if (validationError) { renderErrorState(validationError); return; }

                const thickStr = getStr('board_thick'); 

                const board4864Cont = document.getElementById('board_4864_container');
                const board4896Cont = document.getElementById('board_4896_container');
                const board4864Input = document.getElementById('board_4864');
                const board4896Input = document.getElementById('board_4896');
                const board3660Input = document.getElementById('board_3660');

                if (thickStr === '58') {
                    if (board4864Cont) board4864Cont.classList.add('d-none');
                    if (board4896Cont) board4896Cont.classList.add('d-none');
                    if (board4864Input) board4864Input.checked = false;
                    if (board4896Input) board4896Input.checked = false;
                    if (board3660Input) { board3660Input.checked = true; board3660Input.disabled = true; }
                } else {
                    if (board4864Cont) board4864Cont.classList.remove('d-none');
                    if (board4896Cont) board4896Cont.classList.remove('d-none');
                    if (board3660Input) board3660Input.disabled = false;
                }

                let use3660 = board3660Input ? board3660Input.checked : true;
                let use4864 = board4864Input ? board4864Input.checked : false;
                let use4896 = board4896Input ? board4896Input.checked : false;

                if (!use3660 && !use4864 && !use4896) { 
                    use3660 = true; if(board3660Input) board3660Input.checked = true; 
                }

                hbPositionPanels();
            drawWallVisualizer(wallData, use3660, use4864, use4896);

                let boardQty36 = 0; let boardQty48 = 0; let boardQty4896 = 0;
                let boardSku36 = 'HBWB3660' + thickStr; 
                let boardSku48 = thickStr === '58' ? 'HBWB486412' : 'HBWB4864' + thickStr; 
                let boardSku4896 = 'HBWB489612';

                wallData.forEach(function(wall) {
                    if (wall.w > 0 && wall.h > 0) {
                        let areaSqFt = (wall.w * wall.h) / 144;

                        if (use4896) {
                            let num4896 = Math.floor(areaSqFt / 32); 
                            let rem = areaSqFt - (num4896 * 32);

                            if (rem > 0) { 
                                if (use3660 && use4864) {
                                    if (rem <= 15) boardQty36 += 1; 
                                    else if (rem <= 21.33) boardQty48 += 1; 
                                    else boardQty4896 += 1;
                                } else if (use3660 && !use4864) {
                                    if (rem <= 15) boardQty36 += 1; 
                                    else if (rem <= 30) boardQty36 += 2; 
                                    else boardQty4896 += 1;
                                } else if (!use3660 && use4864) {
                                    if (rem <= 21.33) boardQty48 += 1; 
                                    else boardQty4896 += 1;
                                } else {
                                    boardQty4896 += 1;
                                }
                            }
                            boardQty4896 += num4896;

                        } else if (use4864) {
                            let num48 = Math.floor(areaSqFt / 21.33); 
                            let rem = areaSqFt - (num48 * 21.33);

                            if (rem > 0) { 
                                if (use3660) {
                                    if (rem <= 15) boardQty36 += 1; 
                                    else boardQty48 += 1; 
                                } else {
                                    boardQty48 += 1;
                                }
                            }
                            boardQty48 += num48;

                        } else {
                            boardQty36 += Math.ceil(areaSqFt / 15);
                        }
                    }
                });

                if(boardQty36 > 0) bom[boardSku36] = boardQty36; 
                if(boardQty48 > 0) bom[boardSku48] = boardQty48; 
                if(boardQty4896 > 0) bom[boardSku4896] = boardQty4896;

                let totalScrews = (boardQty36 * 15) + (boardQty48 * 22) + (boardQty4896 * 32);
                bom['HBSCREWWASH100'] = Math.ceil(totalScrews / 100);

                let panSku = null; let drainQty = 1; let panQty = 1; let sideExtQty = 0; let baseW = 0; let baseR = 0; let bestPanConfig = null;

                if (activeDrainType === 'center' || activeDrainType === 'offset' || activeDrainType === 'custom') {
                    bestPanConfig = bestPointPan; panSku = bestPointPan.sku; baseW = bestPointPan.w; baseR = bestPointPan.d;
                    if (bestPointPan.uncoveredSqIn > 0) bom['HBLPSP1272EXT'] = Math.ceil((bestPointPan.uncoveredSqIn * 1.1) / 864);
                } 
                else if (isLinear) {
                    const isThin = activeDrainType === 'linear_thin'; let loc = linLocEl ? linLocEl.value : 'back';
                    if (isCurbless) loc = 'entry'; 
                    let trimStyle = trimSelect ? trimSelect.value : 'sight';
                    let bestLin = getBestLinearPan(panW, panD, isThin, loc);
                    bestPanConfig = bestLin;

                    if (bestLin) {
                        panSku = bestLin.sku; panQty = bestLin.panQty; sideExtQty = bestLin.sideExtQty; baseW = bestLin.baseW; baseR = bestLin.baseR;
                        if (loc === 'center_double') { panQty *= 2; sideExtQty *= 2; }
                        if (sideExtQty > 0) { bom['HBSSSP1872EXT'] = sideExtQty; }

                        const reqDrainEdge = (loc === 'back' || loc === 'entry' || loc === 'center_double') ? panW : panD;
                        if (reqDrainEdge > 73.5) {
                            drainQty = Math.ceil((reqDrainEdge - 24) / 73.5); if (drainQty < 1) drainQty = 1;
                            let coverage = drainQty * 73.5; if (reqDrainEdge > coverage) bom['HBLDSLOTEXT'] = Math.ceil((reqDrainEdge - coverage) / 12);
                        }

                        bom['HBLD73'] = drainQty; if (drainQty > 1) { bom['HBLDCOUP'] = drainQty - 1; }
                        let trimSku = null; if (trimStyle === 'shadow') trimSku = 'HBINSHADOW'; else trimSku = 'HBINSI' + getStr('tile_thick');
                        if (trimSku) bom[trimSku] = (loc === 'center_double') ? (drainQty * 2) : drainQty;
                    }
                }

                if (panSku) bom[panSku] = panQty;

                let loweringKitSku = null; let loweringKitQty = 0; let curbSku = null; let curbQty = 0;

                if (isCurbless) {
                    loweringKitSku = 'HBFLJCK'; const floorSqFt = (panW * panD) / 144;
                    loweringKitQty = Math.ceil(floorSqFt / 24) || 1; bom[loweringKitSku] = loweringKitQty;
                } else {
                    const curbStyle = getStr('curb_style'); const curbSize = entryWidth > 60 ? 84 : 60;
                    curbSku = (curbStyle === 'std') ? ('HBSC3124' + curbSize) : ('HBSCM' + curbSize);
                    curbQty = Math.ceil(entryWidth / curbSize) || 1; bom[curbSku] = curbQty;
                }

                let actTrim = trimSelect ? trimSelect.value : 'sight';
                let hasExtensions = (bom['HBLPSP1272EXT'] > 0 || bom['HBSSSP1872EXT'] > 0 || bom['HBTSSSP7212EXT'] > 0);
                let actLoc = isCurbless ? 'entry' : activeLinLoc;

                drawFloorPlan({
                    panW: panW, panD: panD, entryW: entryWidth, activeFormat: activeDrainType, cX: cX, cY: cY,
                    linLoc: actLoc, isBarrierFree: isCurbless, panSku: panSku, baseW: baseW, baseR: baseR,
                    panQty: panQty, sideExtQty: sideExtQty, trimStyle: actTrim, bestPanConfig: bestPanConfig, hasExtensions: hasExtensions
                });

                const panImg = document.getElementById('pan_preview_img'); const panLabelSku = document.getElementById('pan_sku_label');
                if(panLabelSku && panSku) panLabelSku.innerText = "SKU: " + panSku;
                if (panImg) {
                    if (panSku && catalog[panSku] && catalog[panSku].id) { panImg.src = getAbsoluteUrl(`/web/image/product.product/${catalog[panSku].id}/image_256`); panImg.classList.remove('d-none');
                    } else { panImg.classList.add('d-none'); }
                }

                const foundGalleryContainer = document.getElementById('foundation_gallery_container');
                const foundGallery = document.getElementById('foundation_gallery');
                if(foundGallery) foundGallery.innerHTML = '';

                let currentTrimSku = null; let isDoubleSlopeRender = (isLinear && activeLinLoc === 'center_double');
                if (isLinear) {
                    let activeTrimStyle = getStr('linear_trim'); if (isCurbless || isDoubleSlopeRender) activeTrimStyle = 'sight';
                    currentTrimSku = (activeTrimStyle === 'shadow') ? 'HBINSHADOW' : 'HBINSI' + getStr('tile_thick');
                }

                const foundationSkusToCheck = [panSku, 'HBLD73', currentTrimSku, loweringKitSku, curbSku, 'HBLDSLOTEXT', 'HBLDCOUP', 'HBLPSP1272EXT', 'HBSSSP1872EXT', 'HBTSSSP7212EXT'];
                const foundSkus = foundationSkusToCheck.filter(function(sku) { return sku && bom[sku] > 0; });
                const uniqueFoundSkus = [];
                foundSkus.forEach(function(s) { if(uniqueFoundSkus.indexOf(s) === -1) uniqueFoundSkus.push(s); });
                let hasFoundItems = uniqueFoundSkus.length > 0;

                uniqueFoundSkus.forEach(function(sku) {
                    if(catalog[sku]) {
                        let itemName = catalog[sku].name; let imgSrc = catalog[sku].id ? getAbsoluteUrl(`/web/image/product.product/${catalog[sku].id}/image_256`) : ''; let imgHTML = '';
                        if(imgSrc) { imgHTML = `<img src="${imgSrc}" class="border rounded shadow-sm bg-white p-2 mb-2 click-zoom" style="height: 100px; width: 100px; object-fit: cover;" />`;
                        } else { imgHTML = `<div class="border rounded shadow-sm bg-light d-flex align-items-center justify-content-center mb-2" style="height: 100px; width: 100px;"><span class="text-muted" style="font-size: 0.7rem;">No Image</span></div>`; }
                        let qtyBadge = ''; let displayQty = bom[sku]; 
                        if(displayQty > 1) { qtyBadge = `<span class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-hb-green" style="z-index: 5;">${displayQty}</span>`; }
                        if(foundGallery) { foundGallery.innerHTML += `<div class="text-center d-flex flex-column align-items-center justify-content-end" style="width: 140px;"><div class="position-relative">${imgHTML}${qtyBadge}</div><small class="fw-bold d-block text-dark mb-1" style="font-size: 0.8rem; line-height: 1.2;">${itemName}</small><span class="badge bg-light text-dark border px-2 py-1" style="font-size: 0.7rem;">${sku}</span></div>`; }
                    }
                });

                if(foundGalleryContainer) { if(hasFoundItems) foundGalleryContainer.classList.remove('d-none'); else foundGalleryContainer.classList.add('d-none'); }

                const niches = Array.from(document.querySelectorAll('#niche_container select')).map(function(s) { return s.value; }).filter(function(v) { return v !== 'none'; });
                const benches = Array.from(document.querySelectorAll('#bench_container select')).map(function(s) { return s.value; }).filter(function(v) { return v !== 'none'; });

                // DT8_HB_PROD_SEALANT_CATALOGUE_DIM_FIX_20261015_V1: confirmed 10 oz cartridges and 84-inch mini curb; sealant remains a preliminary allowance.
                let totalSqFt = (boardQty36 * 15) + (boardQty48 * 21.33) + (boardQty4896 * 32);
                let totalOunces = totalSqFt; 
                totalOunces += 10; 
                if (isDoubleSlopeRender) totalOunces += 10; 
                if (!isCurbless) totalOunces += (curbQty * 10); 

                let totalExtBlocks = (bom['HBLPSP1272EXT'] || 0) + (bom['HBSSSP1872EXT'] || 0) + (bom['HBTSSSP7212EXT'] || 0);
                totalOunces += (niches.length * 5);
                totalOunces += (benches.length * 5);
                totalOunces += (totalExtBlocks * 5);

                const isSausage = getStr('sealant_size') === 'sausage';
                const sealantSku = isSausage ? 'HBJSSAUS' : 'HBJSCART';
                bom[sealantSku] = isSausage ? Math.ceil(totalOunces / 20) : Math.ceil(totalOunces / 10);

                const galleryContainer = document.getElementById('accessory_gallery_container'); const gallery = document.getElementById('accessory_gallery');
                if(gallery) gallery.innerHTML = ''; let hasAccessories = false;
                const accessorySkusToRender = [].concat(niches, benches, [sealantSku]);

                accessorySkusToRender.forEach(function(sku) {
                    if (sku !== sealantSku) { bom[sku] = (bom[sku] || 0) + 1; } 
                    if(catalog[sku]) {
                        hasAccessories = true; let itemName = catalog[sku].name; let imgHTML = '';
                        if (catalog[sku].id) { imgHTML = `<img src="${getAbsoluteUrl(`/web/image/product.product/${catalog[sku].id}/image_256`)}" class="border rounded shadow-sm bg-white p-2 mb-2 click-zoom" style="height: 120px; width: 120px; object-fit: cover;" />`; } else { imgHTML = `<div class="border rounded shadow-sm bg-light d-flex align-items-center justify-content-center mb-2" style="height: 120px; width: 120px;"><span class="text-muted small">No Image</span></div>`; }
                        const existingGalleryItem = gallery ? gallery.querySelector(`[data-gallery-sku="${sku}"]`) : null;
                        if(existingGalleryItem && sku !== sealantSku) {
                            let badge = existingGalleryItem.querySelector('.gallery-qty-badge');
                            if(!badge) { const relBox = existingGalleryItem.querySelector('.position-relative'); badge = document.createElement('span'); badge.className = "position-absolute top-0 start-100 translate-middle badge rounded-pill bg-hb-green gallery-qty-badge"; badge.style.zIndex = "5"; badge.innerText = "1"; if(relBox) relBox.appendChild(badge); }
                            if(badge) badge.innerText = parseInt(badge.innerText) + 1;
                        } else {
                            if(gallery) { gallery.innerHTML += `<div class="text-center d-flex flex-column align-items-center justify-content-end" style="width: 140px;" data-gallery-sku="${sku}"><div class="position-relative">${imgHTML}</div><small class="fw-bold d-block text-dark mb-1" style="font-size: 0.8rem; line-height: 1.2;">${itemName}</small><span class="badge bg-light text-dark border px-2 py-1" style="font-size: 0.7rem;">${sku}</span></div>`; }
                        }
                    }
                });

                if(galleryContainer) { if(hasAccessories) galleryContainer.classList.remove('d-none'); else galleryContainer.classList.add('d-none'); }
                Object.keys(hbOptionalSelections).forEach(function(sku){
                    if (hbOptionalSelections[sku] > 0 && catalog[sku] && catalog[sku].id) bom[sku] = (bom[sku] || 0) + hbOptionalSelections[sku];
                });
                currentBom = bom; renderTable(bom);
                hbDraw2DLocationPins();
                if(hbSceneCamera.active)hbRender3D();
            } catch (e) {
                console.error("Shower Engine Calculation Error: ", e);
                renderErrorState("⚠️ <strong>We couldn’t update the calculation.</strong> Please review the measurements or options you just changed. If everything looks correct, refresh the page and try again.");
            }
        }

        function renderTable(bom) {
            const tbody = document.getElementById('bom_table_body'); if(!tbody) return; tbody.innerHTML = ''; let grandTotal = 0; let missingPriceCount = 0; // DT8_HB_PRICE_COUNT_V2
            const entries = []; for (const sku in bom) { if (bom.hasOwnProperty(sku)) { entries.push([sku, bom[sku]]); } }

            for (let i = 0; i < entries.length; i++) {
                const sku = entries[i][0];
                const qty = entries[i][1];

                if (qty > 0) {
                    const item = catalog[sku] || { name: 'Requires Custom Quote', price: 0, id: null }; const hasPrice = Boolean(item.id && Number(item.price) > 0); if (!hasPrice) missingPriceCount += 1; const lineTotal = hasPrice ? Number(item.price) * qty : 0; grandTotal += lineTotal;
                    let productUrl = item.id ? getAbsoluteUrl(`/shop/product/${item.id}`) : '#';
                    let nameHtml = item.id ? `<span class="fw-bold d-block text-dark d-print-none" style="font-size: 0.9rem;">${item.name}</span><a href="${productUrl}" target="_blank" class="fw-bold d-none d-print-block text-primary" style="font-size: 0.85rem;">${item.name}</a>` : `<span class="fw-bold d-block text-dark" style="font-size: 0.9rem;">${item.name}</span>`;
                    let imgHtml = ''; if (item.id) { imgHtml = `<a href="${productUrl}" target="_blank" class="d-block"><img src="${getAbsoluteUrl(`/web/image/product.product/${item.id}/image_256`)}" class="border rounded shadow-sm print-bom-img d-none d-print-block" /></a>`; }
                    tbody.innerHTML += `<tr><td class="align-middle" style="width: 70%;"><div class="d-flex align-items-center">${imgHtml}<div>${nameHtml}<small class="text-muted d-block" style="font-size: 0.75rem; line-height: 1.2;">${sku}</small></div></div></td><td class="text-center align-middle text-nowrap"><span class="badge bg-hb-grey rounded-pill">${qty}</span></td><td class="text-end align-middle text-nowrap fw-bold">${hasPrice ? "$" + lineTotal.toFixed(2) : "Price pending"}</td></tr>`;
                }
            }
            const priceLabelType = window.hbIsGuest ? "MSRP" : "Your Cost"; const typeLabel = document.getElementById('total_type_label');
            if(typeLabel) typeLabel.innerText = missingPriceCount ? "Partial priced subtotal (other items require quote):" : ("Estimated Total (" + priceLabelType + "):");
            const gt = document.getElementById('grand_total'); if(gt) gt.innerText = '$' + grandTotal.toFixed(2);
        }

        const allStaticInputs = document.querySelectorAll('input, select');
        allStaticInputs.forEach(function(input) {
            if (!input.classList.contains('wall-name') && !input.classList.contains('wall-w') && !input.classList.contains('wall-h') && input.id !== 'entry_w' && input.id !== 'pan_w') {
                input.addEventListener('change', function() {
                    if (liveCalcTimer) { clearTimeout(liveCalcTimer); liveCalcTimer = null; }
                    calculateEngine();
                });
            }
        });

        let quoteBtn = document.getElementById('add_to_quote_btn');
        if (quoteBtn) {
            quoteBtn.addEventListener('click', function() {
                if (Object.keys(currentBom).some(function(s) { var i = catalog[s]; return currentBom[s] > 0 && (!i || !i.id || !(Number(i.price) > 0)); })) { window.alert('One or more Hydroblok components need a confirmed price. Please contact Dalla Terra before ordering.'); return; }
                let ghostCart = JSON.parse(localStorage.getItem(window.hbCartStorageKey || 'b2b_ghost_cart') || '[]');

                const entries = []; for (const sku in currentBom) { if (currentBom.hasOwnProperty(sku)) { entries.push([sku, currentBom[sku]]); } }

                for (let i = 0; i < entries.length; i++) {
                    const sku = entries[i][0];
                    const qty = entries[i][1];
                    if (qty > 0 && catalog[sku] && catalog[sku].id) {
                        const item = catalog[sku]; 
                        let existingItem = null;
                        for(let j=0; j<ghostCart.length; j++) { if(ghostCart[j].product_id === item.id) existingItem = ghostCart[j]; }
                        if (existingItem) { existingItem.qty += qty; } else {
                            ghostCart.push({ product_id: item.id, qty: qty, price: item.price, name: item.name, code: sku, isSqft: false, sqftPerPcs: 1, pcsPerBox: 1, fullBoxOnly: false });
                        }
                    }
                }
                localStorage.setItem(window.hbCartStorageKey || 'b2b_ghost_cart', JSON.stringify(ghostCart));
                const btn = document.getElementById('add_to_quote_btn'); const originalText = btn.innerHTML;
                btn.innerHTML = '<i class="fa fa-check me-2"></i>Redirecting...'; btn.classList.replace('btn-primary', 'btn-success');
                setTimeout(function() { btn.innerHTML = originalText; btn.classList.replace('btn-success', 'btn-primary'); window.location.href = '/website/action/1771'; }, 650);
            });
        }

        setTimeout(function() { renderWallsUI(); calculateEngine(); }, 150); window.addEventListener('resize', calculateEngine);
    });
